var i=`0691-palava-sauce`;var a=`world-0691`;var n=`LR`;var s=`western-africa`;var o=4;var r=64;var l={en:`Palava Sauce`,ua:`Соус палава`};var g={en:`Palava Sauce is a Liberia classic prepared with yellow onion, garlic, tomato, okra. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Соус палава, страва кухні країни Ліберія зі складниками: жовта цибуля, часник, помідор, бамія. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,150,`g`],[`red-palm-oil`,65,`ml`],[`garlic`,4,`clove`],[`tomato`,220,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 50 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 50 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:50,i:[[`okra`,300,`g`],[`spinach`,380,`g`],[`crayfish`,120,`g`],[`beef-chuck`,450,`g`],[`water`,650,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`scotch-bonnet-pepper`,1,`pcs`],[`table-salt`,null,`to_taste`]]}];var u={slug:i,id:a,country:`LR`,region:s,servings:4,minutes:64,title:l,text:g,steps:d};export{n as country,u as default,a as id,r as minutes,s as region,o as servings,i as slug,d as steps,g as text,l as title};